using System;
using UnityEngine;

namespace Game.Vehicle.Runtime
{
    /// <summary>One tier's materials of the art truck, by slot name (generated by the TRAKT builder, track A7).</summary>
    [CreateAssetMenu(menuName = "Kamion/Vehicle/Truck Material Set", fileName = "TruckMaterials")]
    public sealed class TruckMaterialSet : ScriptableObject
    {
        [Serializable]
        public struct Entry { public string slot; public Material material; }
        public Entry[] entries = new Entry[0];

        public Material Get(string slot)
        {
            foreach (var e in entries) if (e.slot == slot) return e.material;
            return null;
        }
    }
}
